pub fn m31(x:M31,y:M31)->M31{domain([x.0,y.0]);M31(chosen([m(x.0,y.0)])[0])}
pub fn cm31(x:CM31,y:CM31)->CM31{domain(cw(x));domain(cw(y));c(chosen(cm(cw(x),cw(y))))}
pub fn qm31(x:QM31,y:QM31)->QM31{domain(qw(x));domain(qw(y));q(chosen(qm(qw(x),qw(y))))}
pub fn scalar(x:QM31,y:M31)->QM31{domain(qw(x));domain([y.0]);q(chosen(qw(x).map(|v|m(v,y.0))))}
pub fn by_r(x:CM31)->CM31{domain(cw(x));c(chosen(cr(cw(x))))}
pub fn wide(x:WideExact,y:WideExact)->WideExact{domain(x.to_limbs());domain(y.to_limbs());
