            ],
            [
                left[index].c1.a,
                left[index].c1.b,
                left[index].c1.a.add(left[index].c1.b),
            ],
            [left_sum.a, left_sum.b, left_sum.a.add(left_sum.b)],
        ];
        let right_components = [
            [
                right[index].c0.a,
                right[index].c0.b,
                right[index].c0.a.add(right[index].c0.b),
            ],
            [
                right[index].c1.a,
