  if self.count>=4096{return Err(())}let ys=limbs(y);if ys.iter().any(|v|*v>=P){return Err(())}
  let xs=x.to_limbs();let lo=raw([xs[0],xs[1],xs[2],xs[3]],ys);let hi=raw([xs[4],xs[5],xs[6],xs[7]],ys);
