pub const SEMANTIC_BYTES:usize=12903+29*32;
pub const HEADER:usize=16;
#[cfg(not(feature = "private-leaf-salts"))]
pub const INITIAL_QUERY_BYTES:usize=480+128+2*6*7*32;
#[cfg(feature = "private-leaf-salts")]
