                let line_z=line_x.mul(line_x).double().sub(M31::ONE);
                assert_eq!(*geometry.for_query(index),[point.x.inv(),point.y.inv(),line_x.inv(),line_y.inv(),line_z.inv()]);
            }
        }
    }

