                let slots: [alloc::vec::Vec<CM31>; 4] =
                    core::array::from_fn(|_| (0..len).map(|_| cm31(&mut state)).collect());
                let fused = qm31_cm31_dot4(&weights, [&slots[0], &slots[1], &slots[2], &slots[3]]);
                for slot in 0..4 {
