#[path = "LPa_compact.rs"]
mod LPa_compact;

#[cfg(kani)] mod LPc_compact { include!("LPc_compact.rs"); }

#[cfg(kani)] mod LPg_compact { include!("LPg_compact.rs"); }

#[cfg(kani)] mod LPh_compact { include!("LPh_compact.rs"); }

